    "ধরনের প্রযুক্তি গড়ে উঠেছে। এই প্রযুক্তি ব্যবহার করে আমরা আমাদের জীবনকে সহজ এবং অর্থপূর্ণ",
    "করে তুলেছি, আবার কখনো কখনো ভয়ঙ্কর কিছু প্রযুক্তি বের করে শুধু নিজের জীবন নয়, পৃথিবীর",
