    "| স্যানিফোর গ্যালাক্সি | $6 \\times 10^{12}$ | পৃথিবী | $6 \\times 10^{24}$ | মানুষের জন্মানোর পর থেকে অতিক্রান্ত সময় | $8 \\times 10^{12}$ |",
