    "ছোট সংখ্যা বোঝাতে পারব। উপসর্গগুলো টেবিল ১.০৫ এ দেখানো হয়েছে। আমরা দৈনন্দিন জীবনে কিন্তু এগুলো সব সময় ব্যবহার করি। দূরত্ব বোঝানোর জন্য এক হাজার মিটার না বলে এক কিলোমিটার বলি। পানির আয়তন বোঝানোর জন্য এক লিটারের এক শতাংশ না বলে ১০ মিলিমিটার বলি।",
