    "আমরা এই বইয়ে যখনই নতুন একটি রাশিমালা কথা বলব, সাথে সাথেই তার মাত্রাটির কথা বলে দেওয়ার চেষ্টা করব। দেখবে সেটা সব সময় রাশিটিকে বুঝতে অন্যভাবে সাহায্য করবে। এই বইয়ে",
