    "১.৭ পরিমাপের ত্রুটি ও নির্ভুলতা (Error and accuracy of measurements)",
    "ত্রুটি একটি নেতিবাচক শব্দ এবং ‘পরিমাপে ত্রুটি’ বলা হলে আমাদের মনে হয়, যে মানুষটি পরিমাপ করেছে সে তার দায়িত্ব সঠিকভাবে পালন না করায় একটি ত্রুটি হয়েছে। বিষয়টি তা নয়। যে পরিমাপ করছে; তার অবহেলার কারণে কখনো কখনো ত্রুটি হতে পারে কিন্তু আমাদের জানতে হবে যে আমরা যে যন্ত্রপাতি দিয়ে পরিমাপ করি সেগুলো কখনো নির্ভুল নয়। কাজেই কতটুকু নির্ভুলভাবে পরিমাপ করা সম্ভব তার একটি সীমা আছে অর্থাৎ পরিমাপে ত্রুটি থাকা খুবই স্বাভাবিক। তবে পরিমাপ কতটুকু নির্ভুল হয়েছে তারও একটি পরিমাপ থাকতে হয়। কাজেই একটা পরীক্ষা করে পরীক্ষার ফলাফলটি জানানোর সময় সেটি কতটুকু নির্ভুল সেটাও জানিয়ে দিতে পারলে ফলাফলের বিশ্বাসযোগ্যতা অনেক বেড়ে যায়। পরীক্ষার ফলাফলের নির্ভুলতা বের করার জন্য কিছু প্রচলিত নিয়ম জানা থাকলে তোমরাও তোমাদের পরীক্ষার ফলাফলের নির্ভুলতার একটি পরিমাপ দিতে পারবে।",
    "ধরা যাক, তুমি একটি স্কেল দিয়ে বস্তুর দৈর্ঘ্য মাপছ। বস্তুটির দৈর্ঘ্য কত নির্ভুলভাবে মাপতে পারবে সেটি নির্ভর করে তোমার স্কেলটিতে কত সূক্ষ্মভাবে দাগ কাটা হয়েছে তার ওপর। যদি প্রতি 1 cm পরপর দাগ কাটা থাকে, তাহলে উত্তরটি অবশ্যই তুমি নির্দিষ্ট সংখ্যক cm এ প্রকাশ করবে। কিন্তু বস্তুর প্রকৃত দৈর্ঘ্যটি যে হুবহু সেই সংখ্যক cm ছিল তা কিন্তু নয়, সেটি সম্ভবত এর কাছাকাছি ছিল, কাজেই তোমার মাপা দৈর্ঘ্যটির ভেতর একটু অনিশ্চয়তা থাকা সম্ভব, সে কারণে প্রচলিত নিয়মে আমরা প্রকৃত উত্তরের সাথে সেই অনিশ্চয়তাটুকু যোগ করে দিই। অর্থাৎ আমরা যদি দেখি দৈর্ঘ্যটি 4 এর কাছাকাছি, তাহলে আমরা বলব বস্তুটির দৈর্ঘ্য:",
