    "ঘূর্ণন গতি (Circular Motion)",
    "একটি বস্তু যদি একটা নির্দিষ্ট বিন্দু থেকে সমদূরত্ব থেকে বৃত্তাকার পথে ঘুরতে থাকে, তাহলে তার গতিকে বলে ঘূর্ণন গতি। বৈদ্যুতিক পাখা, ঘড়ির কাঁটা এগুলো ঘূর্ণন গতির উদাহরণ হলেও চমকপ্রদ একটা উদাহরণ হচ্ছে আকাশের চাঁদ। চাঁদকে কোনো কিছু দিয়ে পৃথিবীর সাথে বেঁধে রাখা নেই তবু এটা পৃথিবীকে ঘিরে ঘুরছে, শুধু তাই নয়, এটা টুপ করে পৃথিবীতে পড়েও যাচ্ছে না!",
