    "প্রথম সূত্রটি বলছে যে একই উচ্চতা থেকে ছেড়ে দেওয়া হলে যেকোনো বস্তু একই সময়ে নিচে পড়বে অর্থাৎ এটি বস্তুর ভরের উপর নির্ভর করবে না। এটি আমাদের দৈনন্দিন জীবনের অভিজ্ঞতার সাথে খাপ খায় না। এক টুকরো কাগজ আর একটি ছোট পাথর উপর থেকে ছেড়ে দিলে আমরা দেখি পাথরটি আগে এবং কাগজটি পরে নিচে এসে পড়ে। এটি ঘটে বাতাসের বাধার কারণে, বাতাসহীন একটি টিউবে এরকম পরীক্ষা করা হলে কাগজ এবং পাথর একই সময়ে নিচে এসে পড়ে। পড়ন্ত বস্তুর সূত্রগুলো থেকে গ্যালিলিওর প্রথম সূত্রটি বোঝা যায়। তার কারণ পড়ন্ত বস্তুর বেগ বা অতিক্রান্ত উচ্চতার সমীকরণগুলোতে কোথাও বস্তুর ভর নেই, অর্থাৎ ভারী এবং হালকা সব বস্তুর উপরেই মাধ্যাকর্ষণজনিত ত্বরণ সমানভাবে কাজ করে। কাজেই সমান সময়ে অর্জিত বেগ এবং অতিক্রান্ত দূরত্ব সমান।",
    "গ্যালিলিওর দ্বিতীয় সূত্রটি $g$ এর কারণে বেগ বৃদ্ধির সূত্র। আদি বেগ $u$ শূন্য হলে বেগ $v$ অতিক্রান্ত সময় $t$ এর সাথে সমানুপাতিক। গ্যালিলিও এর তৃতীয় সূত্রটি অতিক্রান্ত উচ্চতা $h$ এর সূত্রটি ছাড়া আর কিছু নয়। এই সূত্রটিতে $u = 0$ ধরে নেওয়া হলে আমরা দেখতে পাই অতিক্রান্ত উচ্চতা $t^2$ এর সমানুপাতিক।",
