    "কাজেই তোমরা দেখতে পেলে দূরত্ব-সময়ের একটি লেখচিত্র থেকে শুরু করে আমরা যেকোনো সময়ের বেগ কিংবা ত্বরণ বের করতে পেরেছি। আমরা যত নিখুঁতভাবে এই লেখচিত্র আঁকতে পারব, তত সঠিক ভাবে এই রাশিগুলো বের করতে পারব। এবারে দ্বিতীয় সেটটি নিয়ে লেখচিত্র এঁকে তোমরা বেগ এবং ত্বরণ বের করো।",
