    "এই বলটি আসলে বস্তুটির ওজন। মনে রাখতে হবে এখানে $R$ পৃথিবীর কেন্দ্র থেকে $m$ ভরটি পর্যন্ত দূরত্ব। পৃথিবীপৃষ্ঠ থেকে $m$ ভরের দূরত্ব নয়। যেহেতু পৃথিবীর ব্যাসার্ধ অনেক (প্রায় 6370 km) কাজেই পৃথিবীর পৃষ্ঠে ছোটখাটো উচ্চতাকে ধর্তব্যের মাঝে আনার প্রয়োজন নেই। পৃথিবীর কেন্দ্র থেকে দূরত্ব মাপা হয় কারণ যদি সুষম গোলাকার কোনো বস্তু হয় তাহলে তার সমস্ত ভর কেন্দ্রবিন্দুতে জমা হয়ে আছে ধরে নিলে কোনো ভুল হয় না। (তার কারণ পৃথিবীর প্রত্যেকটা বিন্দুই $m$ ভরকে নিজের দিকে আকর্ষণ করে এবং সবগুলো আকর্ষণ একত্র করা হলে মনে হয় যেন পৃথিবীর সমস্ত ভরটুকুই কেন্দ্রবিন্দুতে জমা হয়ে আছে। এটি প্রমাণ করে দেখানো যায়)।",
