    "তোমার রাবার ব্যান্ড ব্যালেন্স তৈরি হয়ে গেছে, এখন এটি দিয়ে তুমি তোমার আশে পাশের ছোটখাটো জিনিসপত্রের ভর মেপে দেখতে পারবে। তোমার কাছে সত্যিকারের স্প্রিং ব্যালেন্স থাকলে আরো সূক্ষ্মভাবে ভর এবং সেখান থেকে ওজন বের করতে পারবে।",
    "| ক্রমিক সংখ্যা | বস্তুর নাম | ব্যালেন্স থেকে গ্রামে পাওয়া বস্তুর ভর m | কেজিতে বস্তুর ভর M = m/1000 kg | বস্তুর ওজন w = Mg নিউটন |",
    "| :--- | :--- | :--- | :--- | :--- |",
