    "| | | | | |",
    "৩.৮ নিউটনের তৃতীয় গতি সূত্র (Newton's Third Law of Motion)",
    "কোনো বল প্রয়োগ না করলে কী হয় সেটি আমরা জানতে পেরেছি নিউটনের প্রথম সূত্র থেকে। বল প্রয়োগ করলে কী হয় সেটা আমরা জেনেছি নিউটনের দ্বিতীয় সূত্র থেকে। যখন একটি বস্তু অন্য বস্তুর ওপর বল প্রয়োগ করে তখন বস্তু দুটির মাঝে কী ধরনের প্রতিক্রিয়া হয়, সেটি আমরা জানতে পারব নিউটনের তৃতীয় সূত্র থেকে। সূত্রটি এ রকম:",
    "নিউটনের তৃতীয় সূত্র: যখন একটি বস্তু অন্য একটি বস্তুর ওপর বল প্রয়োগ করে তখন সেই বস্তুটিও প্রথম বস্তুটির ওপর বিপরীত দিকে সমান বল প্রয়োগ করে।",
    "পদার্থবিজ্ঞানের বইয়ে সাধারণত যেভাবে নিউটনের তৃতীয় সূত্র লেখা হয়, ‘প্রত্যেকটি ক্রিয়ার (Action) একটা সমান এবং বিপরীত প্রতিক্রিয়া (Reaction) থাকে’, আমরা এখানে সেভাবে লিখিনি। আমাদের এতক্ষণে যেহেতু বল সম্পর্কে খানিকটা ধারণা হয়েছে হঠাৎ করে বলকে ‘ক্রিয়া’ কিংবা ‘প্রতিক্রিয়া’ বললে বিভ্রান্তি হতে পারে। তার চেয়ে বড় কথা, যারা নতুন পদার্থবিজ্ঞান শেখছে তাদের প্রথম প্রশ্নই হয় যে যদি সকল ক্রিয়ার (কোনো একটি বল) একটি বিপরীত প্রতিক্রিয়া",
    "২০২৩"
