    "আমরা এর আগে মহাকর্ষ বল, মাধ্যাকর্ষণ বল এবং স্প্রিংয়ের বল নিয়ে আলোচনা করেছি, এবারে সম্পূর্ণ ভিন্ন একটি বল নিয়ে আলোচনা করব, সেটি হলো ঘর্ষণ বল।",
    "ধরা যাক, একটা টেবিলে কোনো একটা কাঠের টুকরো রয়েছে এবং সেই কাঠের টুকরোর ওপর বল প্রয়োগ করে সেখানে ত্বরণ সৃষ্টি করতে চাচ্ছি। ধরা যাক, ৩.১৫ চিত্রে যেভাবে দেখানো হয়েছে সেভাবে ভরটির ওপর বাম থেকে ডানে F বল প্রয়োগ করছি, দেখা যাবে কাঠের টুকরোয় টেবিলের সাথে কাঠের টুকরোর ঘর্ষণের কারণে একটা ঘর্ষণ বল f তৈরি হয়েছে এবং সেটি ডান থেকে বাম দিকে কাজ করে প্রয়োগ করা বলটিকে কমিয়ে দিচ্ছে।",
    "[চিত্র ৩.১৫ এর নিচে ক্যাপশন]",
    "চিত্র৩.১৫: একটি ভরের উপর বল প্রয়োগ করলে ঘর্ষণের জন্য বিপরীত দিকে একটি বল তৈরি হতে পারে।",
    "এখন তুমি যদি মনে করো ঘর্ষণের ফলে ডান থেকে বাম দিকে একটা ঘর্ষণ বল তৈরি হয়, কাজেই কাঠের টুকরোর ওপরেও যদি বাম দিকে বল প্রয়োগ করি তাহলে প্রয়োগ করা বল আর ঘর্ষণ বল একই দিকে হওয়ার কারণে বাড়তি একটা বল পেয়ে যাব। কিন্তু দেখা যাবে, এবারেও ঠিক বিপরীত",
    "৮৯"
