    "সৃজনশীল প্রশ্ন",
    "১. ফারুক ১০ kg ভরের একটি বাক্স একটি মেঝের উপর দিয়ে সমবলে টেনে নিল। বাক্স ও মেঝের মধ্যকার ঘর্ষণ বলের মান হলো ১.৫ N। বাক্সটিকে টেনে নেওয়ায় এর ত্বরণ হলো ০.৮ ms⁻²। এরপর বাক্সটিকে ঘর্ষণবিহীন মেঝেতে একই বল প্রয়োগ করে টানা হলো।",
