    "তোমরা কি লক্ষ করেছ, কাজ করার কথা বলার সময় আমরা বলেছি ‘বল’টি কাজ করেছে। একজন মানুষ বা একটি যন্ত্র হয়তো বল প্রয়োগ করে কোনো বস্তুকে ঠেলে খানিকটা দূরত্বে নিয়ে যায়। দৈনন্দিন জীবনের ভাষায় আমরা বলি মানুষটি বা যন্ত্রটি কাজ করেছে। পদার্থবিজ্ঞানের ভাষায় সব সময়েই বল কাজ করে, মানুষ বা যন্ত্র নয়। এই বলটি হয়তো একটি মানুষ বা যন্ত্র প্রয়োগ করেছে।",
