    "গতির জন্য বস্তুর যে শক্তি হয় সেটা নিশ্চয়ই একধরনের শক্তি, যাকে বলা হয় গতিশক্তি। আগের অধ্যায়ে বলেছি যে, আমরা রাস্তাঘাটে যে ভয়ানক দুর্ঘটনা ঘটতে দেখি, সেখানে যে ক্ষয়ক্ষতি হয় তার প্রধান কারণ এই গতিশক্তি। একটা বাস-ট্রাক বা গাড়ি যখন প্রচণ্ড বেগে ছুটতে থাকে, তখন তার অনেক বেশি গতিশক্তি থাকে। দুর্ঘটনার সময় এই পুরো শক্তিটার কারণে গাড়ি ভেঙেচুরে যায়, প্রচণ্ড ধাক্কায় মানুষ মারা যায়।",
