    "এবারে এমন একটা উদাহরণ দেওয়া হবে, যেখানে বল প্রয়োগ করে খানিকটা দূরত্ব অতিক্রম করার পরও কোনো গতিশক্তি তৈরি হবে না। মনে করো টেবিলে একটা স্প্রিং ৪.০২ চিত্রে দেখানো উপায়ে রাখা আছে, তুমি স্প্রিংয়ের খোলা মাথায় আঙুল দিয়ে $F$ বল প্রয়োগ করে স্প্রিংকে $x$ দূরত্বে সংকুচিত করে দিয়েছ। এ রকম অবস্থায় তোমার হাত বা স্প্রিং কোনোটিই গতিশীল না, তাই কোথাও কোনো গতিশক্তি নেই। যেহেতু যেদিকে $F$ বল প্রয়োগ করা হয়েছে অতিক্রম করা দূরত্ব $x$ সেই দিকে, তাই কাজটি পজিটিভ। আমাদের কাজের সংজ্ঞা অনুযায়ী এখানে শক্তি সৃষ্টি হওয়ার কথা। কিন্তু সেই শক্তি কোথায়? কোনো কিছু গতিশীল নয়, তাই এখানে নিশ্চিতভাবে কোনো গতিশক্তি নেই।",
    "[চিত্র ৪.০২: স্প্রিংয়ের স্থিরাবস্থা এবং বল প্রয়োগ করে সংকুচিত অবস্থা]",
    "আমরা যারা স্প্রিং ব্যবহার করেছি, তারা অনুমান করতে পারছি যে সংকুচিত স্প্রিংয়ের ভেতর নিশ্চয়ই শক্তিটুকু লুকিয়ে রয়েছে। কারণ আমরা জানি সংকুচিত স্প্রিংটার সামনে একটা $m$ ভরের বস্তু রেখে স্প্রিংটা ছেড়ে দিলে স্প্রিংটা বস্তুটার ওপর বল প্রয়োগ করে একটা দূরত্ব অতিক্রম করাতে পারত, যার অর্থ কাজ করাতে পারত। অর্থাৎ এটি একটি শক্তি, গতিশক্তি না হলেও এটি অন্য এক ধরনের শক্তি। এ ধরনের সঞ্চিত শক্তিকে বলে বিভব শক্তি (Potential Energy)। এই শক্তি কোনো বস্তুর অবস্থা বা অবস্থানের জন্য তৈরি হয়।",
