    "টেবিল ৫.০১ এ তোমাদের পরিচিত কয়েকটি পদার্থের ঘনত্ব দেওয়া হলো। এখানে একটা বিষয় মনে রাখা ভালো, তাপমাত্রা বাড়লে কিংবা কমলে পদার্থের আয়তন বাড়বে কিংবা কমতে পারে। যেহেতু ভরের কোনো পরিবর্তন হয় না তাই পদার্থের ঘনত্ব তাপমাত্রার সাথে পরিবর্তন হতে পারে। সেজন্য পদার্থের ঘনত্বের কথা বলতে হলে সাধারণত সেটি কোন তাপমাত্রায় মাপা হয়েছে সেটিও বলে দিতে হয়।",
