    "তোমরা সবাই নিশ্চয়ই আর্কিমিডিসের নীতি এবং সেই সূত্রের পেছনের গল্পটি জানো। নীতিটি সহজ, কোনো বস্তু তরলে নিমজ্জিত করলে সেটি যে পরিমাণ তরল অপসারণ করে সেইটুকু তরলের সমান ওজন বস্তুটির ওজন থেকে কমে যায়। আমরা এখন এই নীতিটি বের করব। ৫.০৪ চিত্রে দেখানো হয়েছে খানিকটা তরল পদার্থে একটা সিলিন্ডার ডোবানো রয়েছে। (এটি সিলিন্ডার না হয়ে অন্য যেকোনো আকৃতির বস্তু হতে পারত, আমরা হিসাবের সুবিধার জন্য সিলিন্ডার নিয়েছি)। ধরা যাক সিলিন্ডারের উচ্চতা h এবং উপরের ও নিচের প্রস্থচ্ছেদের ক্ষেত্রফল A। আমরা কল্পনা করে নিই সিলিন্ডারটি এমনভাবে তরলে ডুবিয়ে রাখা হয়েছে যেন তার উপরের পৃষ্ঠের গভীরতা h1 এবং নিচের পৃষ্ঠের গভীরতা h2। (তরল কিংবা বায়বীয়) পদার্থের চাপ কোনো নির্দিষ্ট দিকে কাজ করে না। এটি সব দিকে কাজ করে। কাজেই সিলিন্ডারের উপরের পৃষ্ঠে নিচের দিকে যে চাপ কাজ করে তার পরিমাণ",
    "P1 = h1ρg",
