    "কাজেই দ্বিতীয় সিলিন্ডারে প্রয়োগ করা বলের পরিমাণ হবে $F_2 = PA_2 = F_1 \\left( \\frac{A_2}{A_1} \\right)$",
    "তুমি নিশ্চয়ই চমৎকৃত হয়ে দেখতে পাচ্ছ যদি $(A_2/A_1)$ এর মান 100 হয় তাহলে তুমি প্রথম সিলিন্ডারে যে পরিমাণ বল প্রয়োগ করছ দ্বিতীয় সিলিন্ডারে তার থেকে 100 গুণ বল পেয়ে যাচ্ছ! এই পদ্ধতিটি খুব কার্যকর, বড় বড় কলকারখানা কিংবা বিমান নিয়ন্ত্রণে এই পদ্ধতি ব্যবহার করা হয়। তবে তোমরা একটা জিনিস জেনে রাখো এটা বলবৃদ্ধি করণ নীতি। এই পদ্ধতিতে শক্তি কিন্তু মোটেও বাড়ানো যায় না। তুমি প্রথম সিলিন্ডারে যে পরিমাণ শক্তি প্রয়োগ করবে দ্বিতীয় সিলিন্ডারে ঠিক সেই পরিমাণ শক্তি ফিরে পাবে!",
