    "উদাহরণ",
    "প্রশ্ন: দেখাও যে বল বৃদ্ধি করা হলেও যে পরিমাণ শক্তি প্রয়োগ করা হচ্ছে, ঠিক সেই পরিমাণ শক্তি ফিরে পাচ্ছ।",
    "উত্তর: ধরা যাক, ছোট পিস্টনে $F_1$ বল প্রয়োগ করা হয়েছে এবং পিস্টনটি $l_1$ দূরত্ব অতিক্রম করেছে, কাজেই কাজের পরিমাণ",
