    "৫.৬.১ পদার্থের আণবিক গতিতত্ত্ব",
    "একটি কঠিন পদার্থ টেবিলে রাখা হলে কঠিন পদার্থটি টেবিলের যে অংশটুকু স্পর্শ করবে সেখানে এক ধরনের চাপ প্রয়োগ করবে। কঠিন পদার্থ না রেখে আমরা যদি একইভাবে টেবিলে তরল পদার্থ রাখতে চাই সেটি কাজ করবে না, তরলটি সারা টেবিলে গড়িয়ে যাবে। তরলটি রাখতে হবে কোনো একটা পাত্রে এবং তরলটি শুধু নিচে নয় চারদিকে পাত্রটির গায়ে চাপ দেবে। (পাত্রটির গায়ে একটা ফুটো করা হলে তরলের চাপে এই ফুটো দিয়ে তরল বের হতে থাকবে) আমরা যদি গ্যাস রাখতে চাই, তাহলে সেটি আর পাত্রে রাখা সম্ভব না, তখন সেটি একটা আবদ্ধ জায়গায় রাখতে হবে এবং গ্যাস এই আবদ্ধ জায়গার চারদিকে চাপ প্রয়োগ করবে। একটা বেলুন ফুলিয়ে সেখানে গ্যাস রাখা হয় এবং বেলুনটা না ফাটিয়ে সেখানে একটা ফুটো করতে পারলে বাতাসের চাপে এই ফুটো দিয়ে বাতাস বের হতে থাকবে।",
