    "তত্ত্ব: বস্তুর ভরকে বস্তুর আয়তন দিয়ে ভাগ দেওয়া হলে ঘনত্ব বের হয়। বস্তুর ভর স্প্রিং ব্যালেন্স দিয়ে বের করা যায়। বস্তুর আয়তন আর্কিমিডিসের সূত্র দিয়ে বের করা সম্ভব, পানিতে ডোবালে তার ভর যত গ্রাম কমে যাবে, বস্তুর আয়তন তত সিসি (cm³)।",
