  "164": [
    "ষষ্ঠ অধ্যায়, বস্তুর ওপর তাপের প্রভাব",
    "(Effects of Heat on Matter)",
    "তাপ হচ্ছে একধরনের শক্তি। শক্তির ধারণা থেকে আমাদের মনে হতে পারে বেশি তাপশক্তি থেকে বুঝি সব সময়েই তাপ কম তাপশক্তির দিকে যায়; কিন্তু সেটি সত্যি নয়। তাপশক্তি কোন দিকে যাবে সেটি নির্ভর করে তাপমাত্রার উপর। এই অধ্যায়ে আমরা তাপ এবং তাপমাত্রা কীভাবে পরিমাপ করতে পারি এবং দুইয়ের মাঝে কী সম্পর্ক সেটি দেখব।",
    "তাপশক্তিটুকু আসলে বস্তুর অণু-পরমাণুর গতি বা কম্পন থেকে এসেছে। তাপ দিয়ে কোনো কঠিন বস্তুর অণুগুলোর কম্পন যদি অনেক বাড়িয়ে দেওয়া যায়, তাহলে একটি অণু অন্য অণু থেকে সরে যেতে পারে অর্থাৎ অবস্থার পরিবর্তন হতে পারে। এই অধ্যায়ে আমরা কঠিন, তরল এবং গ্যাসের ওপর তাপের প্রভাব নিয়ে আলোচনা করব।"
  ],
