    "বরফটুকু গলতে এবং বরফ গলা পানির চূড়ান্ত তাপমাত্রায় পৌঁছাতে যে তাপের প্রয়োজন হবে সেই তাপটুকু 1 kg পানিকে সরবরাহ করতে হবে। ধরা যাক পানির চূড়ান্ত তাপমাত্রা $T$, তাহলে বরফ যে পরিমাণ তাপ গ্রহণ করবে সেগুলো হলো:",
