    "একটি আলোকোজ্জ্বল জায়গায় বড় একটি থালায় খানিকটা পানি ঢেলে নাও। থালায় যেন অন্য কোনো কম্পন না থাকে সেটি নিশ্চিত করো। পানির যেকোনো বিন্দু স্পর্শ করলে সেই বিন্দু থেকে চারদিকে তরঙ্গা ছড়িয়ে পড়বে এবং থালার তলায় তুমি তার প্রতিচ্ছবি দেখতে পাবে। থালার পানির ঠিক কেন্দ্রে স্পর্শ করলে দেখবে, একটি তরঙ্গা সেখান থেকে শুরু হয়ে থালার কিনারায় গিয়ে সেখান থেকে প্রতিফলিত হয়ে কেন্দ্রে মিলিত হবে। তরঙ্গটি ঠিক ভাবে তৈরি করতে পারলে সেটি কেন্দ্রে মিলিত হওয়ার পর আবার পাশে ছড়িয়ে পড়বে। তুমি একটুখানি চেষ্টা করলেই এই তরঙ্গের বেগ মাপতে পারবে। চেষ্টা করে দেখো।",
