    "সরল স্পন্দন গতিতে আমরা যে সকল রাশির কথা বলেছি, তার সবগুলোই আসলে পর্যায়বৃত্ত তরঙ্গের বেলায় ব্যবহার করতে পারব। তরঙ্গের পূর্ণ স্পন্দন হয়; তার পর্যায়কাল আছে, কম্পাঙ্ক আছে এবং বিস্তার আছে। আমরা দেখেছি কোনো একটা তরঙ্গ প্রবাহিত হওয়ার সময় আমরা যদি মাধ্যমের কোনো একটা কণার দিকে তাকিয়ে থাকি, তাহলে দেখব সেই কণাটির সরল স্পন্দিত কম্পন হচ্ছে।",
    "তরঙ্গের বেলায় আমরা নতুন দুটি রাশির কথা বলতে পারি যার একটা হচ্ছে তরঙ্গদৈর্ঘ্য। তরঙ্গের যেকোনো একটি দশা থেকে তার পরবর্তী একই দশার মাঝে দূরত্ব হচ্ছে তার তরঙ্গদৈর্ঘ্য (চিত্র ৭.০৪)। অর্থাৎ এক পর্যায়কালে একটা তরঙ্গ যেটুকু দূরত্ব অতিক্রম করে সেটাই হচ্ছে তরঙ্গ দৈর্ঘ্য।",
