    "৭.৩.৩ শব্দের ব্যবহার (Uses of Sound)",
    "শব্দের প্রচলিত ব্যবহারের কথা নিশ্চয়ই আর কাউকে আলাদা করে বলতে হবে না। আমরা কথা বলি, গান শুনি, ডাক্তাররা হৃদস্পন্দন শোনেন, ইঞ্জিনিয়াররা যন্ত্রপাতির শব্দ শোনেন ইত্যাদি। শব্দের আরো কিছু ব্যবহার আছে, যার কথা তোমরা হয়তো শোনোনি। সন্তানসম্ভবা মায়ের গর্ভে যে নবজাতকটি বড় হয় বাইরে থেকে তাকে দেখার কোনো উপায় ছিল না। এখন আল্ট্রাসনোগ্রাফি নামে একটি প্রক্রিয়ায় সেটি দেখা সম্ভব হয়।",
    "ত্রিমাত্রিক সিসমিক সার্ভে (3D Seismic Survey)",
    "মাটির নিচে গ্যাস বা তেল আছে কি না দেখার জন্য সিসমিক সার্ভে করা হয়। এটি করার জন্য মাটির খানিকটা নিচে ছোট বিস্ফোরণ ঘটানো হয়, বিস্ফোরণের শব্দ মাটির নিচের বিভিন্ন স্তরে প্রতিফলিত হয়ে উপরে ফিরে আসে। জিওফোন (Geophone) নামে বিশেষ এক ধরনের রিসিভারে সেই প্রতিফলিত তরঙ্গকে ধারণ (Detect) করা হয় (চিত্র ৭.১৩)। সমস্ত তথ্য বিশ্লেষণ করে মাটির নিচের নিখুঁত ত্রিমাত্রিক ছবি বের করে, কোথায় গ্যাস বা কোথায় তেল আছে তা বের করা যায়। শব্দের উৎসটি কোথায় আছে এবং জিওফোনগুলো কোথায় আছে দুটিই জানা থাকার কারণে উৎস থেকে জিওফোনে শব্দ আসতে কতটুকু সময় লেগেছে জানতে পারলেই বিভিন্ন স্তরের দূরত্ব নিখুঁতভাবে বের করা যায়।",
    "চিত্র ৭.১৩: শব্দ তরঙ্গে প্রতিফলন থেকে ভূপৃষ্ঠের ভিন্ন ভিন্ন স্তর সম্পর্কে তথ্য জানা যায়।"
