    "আলোর উৎস নেই। আমরা পরে দেখব অনেক সময় কিন্তু সত্যি সত্যি এমনভাবে একটা প্রতিবিম্ব তৈরি হয়, যেখানে সত্যি সত্যি আলো কেন্দ্রীভূত হয় এবং সেখান থেকে আলোক রশ্মি বের হয়ে আসে। এ রকম প্রতিবিম্বকে বলে বাস্তব প্রতিবিম্ব এবং এই ধরনের প্রতিবিম্ব দিয়ে অনেক কাজ করা সম্ভব। আয়নায় যে প্রতিবিম্ব তৈরি হয় সেখানে সত্যিকারের আলো কেন্দ্রীভূত হয় না, তাই এর নাম অবাস্তব প্রতিবিম্ব।",
    "৮.১০ চিত্রে একটি মাত্র বিন্দু না হয়ে একটা বিস্তৃত বস্তুর প্রতিবিম্ব কীভাবে তৈরি হয় দেখানো হয়েছে। X এবং Y বিন্দু থেকে আলো আয়নায় প্রতিফলিত হয়ে যথাক্রমে X' এবং Y' এ অবাস্তব প্রতিবিম্ব তৈরি করেছে অর্থাৎ মনে হচ্ছে চোখে আলোক রশ্মি আসছে X' এবং Y' থেকে। দেখাই যাচ্ছে XY এর যে দৈর্ঘ্য X'Y' এর সেই একই দৈর্ঘ্য। XY তে তীরের মাথাটি যদি উপরের দিকে হয় তাহলে X'Y' তেও তীরের মাথাটি উপরের দিকে হবে। অর্থাৎ সাধারণ আয়নায় কিংবা দর্পণে প্রতিবিম্ব:",
