    "উত্তর: AOB তে তোমার প্রকৃত হাত। A'OB তে তোমার হাতের সামনা-সামনি প্রতিবিম্ব। ঠিক সেরকম AOB' তে তোমার হাতের উপর-নিচ প্রতিবিম্ব। লক্ষ্য করো, দুই ক্ষেত্রেই বাম হাতের প্রতিবিম্ব ডান হাত হিসেবে এসেছে। A'OB' ক্ষেত্রে প্রতিবিম্বের প্রতিবিম্ব দেখা যাবে। এটি A'OB এর প্রতিবিম্বের উপর-নিচ প্রতিবিম্ব হতে পারে, আবার AOB' এর প্রতিবিম্বের সামনা-সামনি প্রতিবিম্ব হতে পারে। লক্ষ্য করো একবার প্রতিফলনে বাম হাত ডান হাত হয়ে গিয়েছিল কিন্তু দুইবার প্রতিফলনে (প্রতিফলনের প্রতিফলনে) বাম হাত আবার বাম হাত হিসেবেই এসেছে।",
