    "সাধারণ সমতল আয়না আমরা সবাই দেখেছি কিন্তু সত্যিকারের গোলীয় আয়না আমরা সবাই নাও দেখে থাকতে পারি—তবে গোলীয় আয়নার মূল বিষয়টি কিন্তু চকচকে নতুন চামচে অনেকটা দেখা যায়। গোলীয় আয়না দুই রকমের হয়ে থাকে—অবতল এবং উত্তল। একটা ফঁাপা গোলকের খানিকটা কেটে তার পৃষ্ঠে রুপা বা অ্যালুমিনিয়ামের প্রলেপ লাগিয়ে অবতল কিংবা উত্তল গোলীয় আয়না তৈরি করা যায়। কোন পৃষ্ঠে রুপা বা অ্যালুমিনিয়ামের প্রলেপ দেওয়া হবে তার ওপর নির্ভর করবে এই গোলীয় আয়নাটি অবতল না উত্তল গোলীয় আয়না হবে।",
