    "তোমরা যদি কখনো একটা চকচকে চামচের নিচে বা পেছনের অংশে নিজের চেহারা দেখার চেষ্টা করে থাকো (চিত্র ৮.১৬) তাহলে নিশ্চয়ই লক্ষ্য করেছ যে, সেখানে তুমি তোমার চেহারাটা সোজা দেখালেও সেটি হবে তুলনামূলকভাবে ছোট। চামচের এই অংশটা উত্তল আয়নার মতো কাজ করে। সত্যিকারের গোলকীয় উত্তল আয়না একটা প্রকৃত গোলকের অংশ হয়। ধরা যাক, গোলকটির ব্যাসার্ধ r (চিত্র ৮.১৭) এবং তার একটা অংশ কেটে তার উত্তল অংশটির দিক থেকে আলোর প্রতিফলনের ব্যবস্থা করা হয়েছে। এই আয়নায় একটা সমান্তরাল আলো ফেলা হলে আলোটি চারদিকে ছড়িয়ে যাবে, ছড়িয়ে যাওয়া আলোক রশ্মিগুলো যদি আয়নাটি যে গোলকের অংশ তার ভিতরে দিকে বর্ধিত করি তাহলে মনে হবে সেটা বুঝি একটা বিন্দু থেকে ছড়িয়ে গেছে। ঐ বিন্দুটিকে বলে ফোকাস বিন্দু। উত্তল আয়নার যে পৃষ্ঠ থেকে প্রতিফলন হয় তার কেন্দ্রবিন্দুটিকে বলে মেরু বিন্দু এবং এই বিন্দু থেকে ফোকাস বিন্দুর দূরত্বটিকে ফোকাস দূরত্ব (f) বলে।",
    "একটা গোলীয় আয়নাকে আমরা সব সময় একটা গোলকের অংশ হিসেবে কল্পনা করতে পারি। ঐ গোলকটির ব্যাসার্ধ যদি r হয় তাহলে ফোকাস দূরত্ব r/2 হবে।",
