    "আমরা এখন এই তিনটি নিয়ম ব্যবহার করে প্রতিবিম্ব তৈরি করতে পারব। ৮.১৯ চিত্রে একটা উত্তল আয়নার সামনে XY একটি বস্তু রাখা আছে Y বিন্দু থেকে আলো R বিন্দুতে এলে সেটি লম্বভাবে ফিরে যায়, যার অর্থ XY বস্তুর Y বিন্দুর প্রতিবিম্বটি এই YO রেখার কোথাও হবে। সেটি ঠিক কোথায় জানতে হলে X বিন্দু থেকে অন্যদিকে আরেকটি রশ্মি আঁকতে হবে, আমাদের সেটি করার প্রয়োজন নেই কারণ X বিন্দুটির প্রতিবিম্বটি বের করে সেখান থেকে আমরা এটি জেনে নেব।",
    "X বিন্দুর প্রতিবিম্ব বের করার জন্য দুটি রশ্মি আঁকতে হবে, একটি আগের মতো সরাসরি O বিন্দুর সাথে যুক্ত করি। YR রশ্মিটি যে রকম লম্বভাবে প্রতিফলিত হয়ে Y এর দিকে ফিরে গিয়েছিল এই রশ্মিটিও ঠিক একইভাবে N বিন্দুতে প্রতিফলিত হয়ে X এর দিকে ফিরে যাবে। দ্বিতীয় রশ্মিটি YR এর সাথে সমান্তরালভাবে আঁকা যেতে পারে, সেটা উত্তল আয়নার P বিন্দুতে আপতিত হয়ে প্রতিফলিত হবে এবং মনে হবে যেন F বিন্দু থেকে ছড়িয়ে যাচ্ছে কাজেই আমরা FP কে যুক্ত করে Q এর দিকে বাড়িয়ে দিতে পারি।",
