    "দেখাই যাচ্ছে X'Y' সব সময় XY থেকে ছোট এবং XY উত্তল আয়না থেকে যত দূরে থাকবে X'Y' হবে তত ছোট। প্রতিফলনের নিয়ম ব্যবহার করে উত্তল কিংবা অবতল আয়নায় প্রতিবিম্ব আঁকার এই পদ্ধতিটি ভালো করে জেনে রাখা দরকার, এটি পদার্থবিজ্ঞানের খুব প্রয়োজনীয় একটা পদ্ধতি।",
    "বোঝাই যাচ্ছে X'Y' থেকে আসলে সত্যিকারের আলো বিচ্ছুরিত হচ্ছে না, আমাদের শুধু মনে হচ্ছে বুঝি প্রতিবিম্বটি এখানে আছে। কাজেই এটা অবাস্তব প্রতিবিম্ব। সাধারণ আয়নার প্রতিবিম্বের সাথে তুলনা করে আমরা বলতে পারি।",
    "(a) এই প্রতিবিম্বটির অবস্থান হবে ফোকাস বিন্দু এবং মেরু বিন্দুর মাঝখানে। বস্তুটি যত দূরে থাকবে প্রতিবিম্বটি ফোকাস বিন্দুর তত কাছে তৈরি হবে।",
    "(b) এই প্রতিবিম্বটি অবাস্তব",
    "(c) এটি সোজা",
    "(d) এটা ছোট, বস্তুটি আয়না থেকে যত দূরে যাবে প্রতিবিম্বটি তত ছোট হতে থাকবে।",
    "৮.৬ অবতল গোলীয় আয়না (Concave Mirror)",
    "একটা চকচকে চামচের ভেতরের অংশটা অবতল গোলীয় আয়নার উদাহরণ হতে পারে। তোমরা যারা চামচের ভেতরের দিকে তাকিয়েছ, তারা নিশ্চয়ই লক্ষ্য (চিত্র ৮.২০) করেছ সেখানে তোমার প্রতিবিম্বটি ছোট এবং সবচেয়ে চমকপ্রদ হচ্ছে যে প্রতিবিম্বটি উল্টো। তোমরা চাইলে তোমার আঙুল চামচটার খুব কাছে এনে দেখতে পারো, তখন দেখবে আঙুলটা সোজাই দেখাচ্ছে। এবারে আস্তে আস্তে দূরে সরাতে থাক, দেখবে তোমার আঙুলটা বড় দেখাতে শুরু করেছে (আমরা সমতল আয়না কিংবা উত্তল আয়নার আগে প্রতিবিম্ব তৈরি করতে পেরেছি কিন্তু কখনোই বস্তুর প্রকৃত আকার থেকে বড় প্রতিবিম্ব তৈরি করতে পারিনি—এই প্রথম বড় প্রতিবিম্ব দেখতে",
    "চিত্র ৮.২০: একটি চামচের ভেতরের অংশ অবতল গোলীয় আয়নার মতো কাজ করে।"
