    "বাস্তব প্রতিবিম্ব খুবই গুরুত্বপূর্ণ একটি ধারণা। আমরা পরের অধ্যায়ে দেখব কেমন করে লেন্স দিয়েও এ রকম বাস্তব প্রতিবিম্ব তৈরি করা যায়। তোমরা দেখতেই পেয়েছ বাস্তব প্রতিবিম্বে সত্যিকারের আলোক রশ্মি থাকে, তাই এটাকে যদি কোনো পর্দায় ফেলা যায়, সেখানে প্রতিবিম্বটি দেখাও সম্ভব হয়। সাধারণ বা সমতল আয়নায় তুমি তোমার চেহারা দেখতে পারবে কিন্তু শুধু সাধারণ আয়না দিয়ে কখনো তোমার চেহারা কোনো পর্দায় ফেলতে পারবে না।",
