    "উত্তল আয়নায় যেহেতু সোজা এবং ছোট প্রতিবিম্ব তৈরি করা যায়, তাই বড় কোনো দৃশ্যকে ছোট জায়গায় দেখতে হলে উত্তল আয়না ব্যবহার করা হয়। গাড়ির দক্ষ ড্রাইভাররা গাড়ি চালানোর সময় সব সময় পেছনে কী হচ্ছে দেখার চেষ্টা করেন, সে জন্য গাড়ির ড্রাইভারের সামনে রিয়ার ভিউ মিরর থাকে। এই মিররগুলোতে উত্তল আয়না ব্যবহার করা হয় যেন ছোট একটা আয়না দিয়েই গাড়ির ড্রাইভাররা পেছনের বড় একটা জায়গা দেখতে পারেন।",
