    "অবতল আয়নার সবচেয়ে বড় ব্যবহার হচ্ছে টেলিস্কোপে। পৃথিবীর সবচেয়ে বড় এবং সবচেয়ে সূক্ষ্ম টেলিস্কোপে অবতল আয়না ব্যবহার করা হয়। অনেকে সাধারণভাবে মনে করে দূরের কোনো ছোট জিনিসকে অনেক বড় করে দেখানোই বুঝি ভালো টেলিস্কোপের দায়িত্ব। আসলে সেটি সত্যি নয়, ভালো টেলিস্কোপের দায়িত্ব অনেক কম আলোতেও স্পষ্ট প্রতিবিম্ব তৈরি করা। সেজন্য অবতল আয়নার আকার যত বড় হবে, সেটি তত বেশি আলো সংগ্রহ করে তত স্পষ্ট প্রতিবিম্ব তৈরি করতে পারবে। পৃথিবীর সব বড় বড় টেলিস্কোপে অবতল আয়না ব্যবহার করা হয়।",
    "অবতল আয়নার আরেকটি ব্যবহার হচ্ছে আলোকের সমান্তরাল বিম বা রশ্মি গুচ্ছ তৈরি করা। জাহাজ বা লঞ্চের সার্চলাইটে অবতল আয়না ব্যবহার হয়।",
