    "অবতল আয়নায় ফোকাস দূরত্বের ভেতরে কিছু থাকলে যেহেতু সোজা এবং বড় প্রতিবিম্ব তৈরি হয় তাই কোনো কিছু বড় করে দেখতে হলেও অবতল আয়না ব্যবহার করা হয়। ডাক্তার কিংবা ডেন্টিস্টরা তাই অনেক সময়ই কিছু দেখার জন্য অবতল আয়না ব্যবহার করেন।",
