    "কাজেই $75^\\circ$ তে আলো আপতিত হলে সেটি প্রতিসরিত না হয়ে পূর্ণ অভ্যন্তরীণ প্রতিফলন হবে।",
    "৯.২.১ রংধনু",
    "তোমরা যারা ভাবছ যে তোমরা সত্যি সত্যি কখনো পূর্ণ অভ্যন্তরীণ প্রতিফলন দেখনি, তাদেরকে মনে করিয়ে দেওয়া যায় যে যারা রংধনু দেখেছে তারাই পূর্ণ অভ্যন্তরীণ প্রতিফলন দেখেছে। রংধনু তৈরি হয় পানির পূর্ণ অভ্যন্তরীণ প্রতিফলন দিয়ে।",
    "শুধু তা-ই নয়, যারা প্রিজমের অভাবে সাদা আলোকে তার রংগুলোতে ভাগ করে দেখতে পারোনি তারাও এই ব্যাপারটি রংধনুতেই ঘটতে দেখেছ। বৃষ্টি হওয়ার পরপর যদি রোদ ওঠে, তাহলে আমরা রংধনু দেখি। তার কারণ তখন বাতাসে পানির কণা থাকে এবং পানির কণায় সেই আলো পূর্ণ অভ্যন্তরীণ প্রতিফলিত হওয়ার সময় ভিন্ন ভিন্ন রঙের আলো ভিন্ন ভিন্ন পরিমাণে বেঁকে যায়। এই আলোর রশ্মিগুলো দিয়ে রংধনুর ভিন্ন ভিন্ন রঙের ব্যান্ড (Band) তৈরি হয়।",
    "চিত্র ৯.০৯ : রংধনু",
    "তোমরা যারা রংধনু দেখেছ তারা নিশ্চয়ই আবিষ্কার করেছ এটি সব সময় সূর্যের বিপরীত আকাশে দেখা যায় এবং এখন তার কারণটি নিশ্চয়ই বুঝতে পারছ।",
    "ভরদুপুরে রংধনু দেখা যায় না কেন?",
    "৯.২.২ মরীচিকা",
    "মরুভূমিতে মরীচিকা খুবই পরিচিত দৃশ্য। তোমরা হয়তো শুনে অবাক হবে যে মরীচিকাও রংধনুর মতো পূর্ণ অভ্যন্তরীণ প্রতিফলনের কারণে ঘটে থাকে।",
    "কোনো কিছু পাওয়ার আশা করে শেষ পর্যন্ত না পেলে সেটাকেও মরীচিকা বলা হয় কিন্তু মূল শব্দটি এসেছে মরুভূমিতে উষ্ণ স্থানে সৃষ্টি এক ধরনের দৃষ্টি বিভ্রম থেকে। যদিও আমরা জানি উত্তপ্ত বাতাস হালকা বলে উপরে চলে যায় কিন্তু মরুভূমির উত্তপ্ত বালুর কারণে তার কাছাকাছি স্তরের বাতাস উপরের স্তরের বাতাস থেকে উত্তপ্ত থাকতে পারে। কাজেই মরুভূমির বাতাসকে আমরা ৯.১০ চিত্রের মতো করে কল্পনা করে নিতে পারি।",
