    "প্রিজমে আলোর দিক পাল্টে যাবার ঘটনা ঘটলেও সেটি অন্য একটি কারণে আরো বেশি গুরুত্বপূর্ণ। প্রিজমে একটি আলোক রশ্মি প্রবেশ করার পর সেটি মূল দিক থেকে কতটুকু বেঁকে যাবে সেটি প্রিজমের প্রতিসরণাঙ্কের ওপর নির্ভর করে। আমরা আগেই বলেছি, প্রতিসরণাঙ্ক আসলে আলোর তরঙ্গ দৈর্ঘ্য বা রঙের ওপর নির্ভর করে। তাই ভিন্ন ভিন্ন রঙের জন্য প্রতিসরণাঙ্ক ভিন্ন, কাজেই একই আলোক রশ্মিতে ভিন্ন ভিন্ন রং থাকলে প্রিজমের ভেতর দিয়ে যাওয়ার সময় সেই রঙের আলোগুলো ভিন্ন ভিন্ন কোণে দিক পরিবর্তন করবে। কাজেই আমরা দেখব প্রিজম থেকে আলো বের হবার সময় তার রংগুলো আলাদা হয়ে গেছে, নিউটন প্রথম দেখিয়েছিলেন।",
