    "উদাহরণ",
    "প্রশ্ন: দুটি ধাতব গোলক রয়েছে। একটি পজিটিভ চার্জযুক্ত কাচের দণ্ড দিয়ে দুটি গোলককে কি দুই রকমের চার্জ তৈরি করতে পারবে?",
