    "উত্তর: হ্যাঁ ১০.০৬ চিত্রটিতে যেভাবে দেখানো হয়েছে, সেভাবে দুটো গোলককে ভিন্ন চার্জ আবেশিত করে আলাদা করা সম্ভব।",
    "এই অধ্যায়ের শুরুতে আমরা তিনটি ভিন্ন ভিন্ন ঘটনার কথা বলেছিলাম। এতক্ষণে সেগুলো কেন ঘটেছে তোমরা নিশ্চয়ই সেটা বুঝে গেছ। চিরুনির বিষয়টা ব্যাখ্যা করা হয়েছে। ছোট শিশুর হামাগুড়ি দেওয়ার বিষয়টাও বোঝা কঠিন নয়। কার্পেটে ঘষে ঘষে যাবার জন্য তার শরীরে চার্জ জমা হয়, সারা শরীরের সাথে সাথে চুলে ও সেই চার্জ ছড়িয়ে পড়ে। সব চুলে একই চার্জ। আমরা জানি এক ধরনের চার্জ বিকর্ষণ করে তাই একটা চুল অন্য চুলকে বিকর্ষণ করে খাড়া হয়ে ছড়িয়ে পড়ে। এখন আমরা বজ্রপাতের বিষয়টাও ব্যাখ্যা করতে পারব। মেঘের সাথে মেঘের ঘর্ষণে সেখানে চার্জ আলাদা হয়ে যায়। আকাশের মেঘে যখন বিপুল পরিমাণ চার্জ জমা হয় তখন সেটা নিচে বিপরীত চার্জের আবেশ তৈরি করে এবং মাঝে মাঝে সেটা এত বেশি হয় যে বাতাস ভেদ করে সেটা মেঘের সাথে যুক্ত হয়ে যায়, যেটাকে আমরা বজ্রপাত বলি। (চিত্র ১০.০৭)",
