    "ইলেকট্রোস্কোপ স্থির বিদ্যুৎ পরীক্ষার জন্য খুব চমৎকার একটা যন্ত্র। যন্ত্রটা খুবই সহজ, এখানে চার্জের অস্তিত্ব বোঝার জন্য রয়েছে খুবই হালকা সোনা, অ্যালুমিনিয়াম বা অন্য কোনো ধাতুর দুটি পাত। এই পাত দুটো একটা সুপরিবাহী দণ্ড দিয়ে একটা ধাতব চাকতির সাথে লাগানো থাকে, পুরোটা একটা অপরিবাহী ছিপি দিয়ে কাচের বোতলের ভেতর রাখা হয়, যেন বাইরে থেকে দেখা যায় কিন্তু বাতাস বা অন্য কিছু যেন পাতলা ধাতব পাত দুটোকে নাড়াচাড়া করতে না পারে।",
    "চার্জ আহিতকরণ",
    "একটা কাচের টুকরোকে সিল্ক দিয়ে ঘষা হলে কাচ দণ্ডটাতে পজিটিভ চার্জ জমা হবে। এখন কাচ দণ্ডটা যদি ইলেকট্রোস্কোপের ধাতব চাকতিতে ছোঁয়ানো যায় তাহলে সাথে সাথে খানিকটা চার্জ চাকতিতে চলে যাবে। চাকতি যেহেতু ধাতব দণ্ড আর সোনার পাতের সাথে লাগানো আছে, তাই চার্জটুকু সব জায়গায় ছড়িয়ে পড়বে। সোনার পাতে যখন একই পজিটিভ চার্জ এসে হাজির হবে আর তখন দেখা যাবে পাত দুটো বিকর্ষণ করে তাদের মাঝে একটা ফাঁক তৈরি হয়েছে।",
    "ঠিক একইভাবে একটা চিরুনিকে যদি ফ্লানেল দিয়ে ঘষা হয় তাহলে চিরুনিটাতে নেগেটিভ চার্জ জমা হবে। এখন সেটা যদি চাকতিতে স্পর্শ করা হয় তাহলে নেগেটিভ চার্জ সোনার পাত পর্যন্ত ছড়িয়ে পড়বে এবং দুটো পাত একটা আরেকটাকে বিকর্ষণ করে ফাঁক হয়ে যাবে।",
