    "দিতে হবে। ধরা যাক কাচকে সিল্ক দিয়ে ঘষে পজিটিভ চার্জ তৈরি করে আমরা সেটাকে চাকতিতে স্পর্শ করলে যদি সোনার পাত দুটির ফাঁক কমে যায় তাহলে বুঝতে হবে এর মাঝে নেগেটিভ চার্জ। যদি ফাঁকটি আরো বেড়ে যায় তাহলে বুঝতে হবে চার্জটি নিশ্চয়ই পজিটিভ।",
