    "যদি পজিটিভ চার্জ দেওয়া কোনো কিছু না এনে নেগেটিভ চার্জ দেওয়া কিছু আনি তাহলেও আমরা দেখব সোনার পাত দুটো ফাঁক হয়ে যাচ্ছে, তবে এবারে সেটি হবে সেখানে নেগেটিভ চার্জ জমা হওয়ার কারণে।",
    "বর্ষাকালে স্থির বিদ্যুতের পরীক্ষাগুলো ঠিক করে কাজ করে না কেন?",
    "১০.৪ বৈদ্যুতিক বল (Electric Force)",
    "আমরা একটু আগেই দেখেছি, বিপরীত চার্জ একে অন্যকে আকর্ষণ করে কিন্তু এক ধরনের চার্জ একে অন্যকে বিকর্ষণ করে। তবে আমরা এখনো জানি না ঠিক কতখানি আকর্ষণ কিংবা বিকর্ষণ করে, সেটা বুঝতে হলে আমাদের কুলম্বের সূত্রটি একটুখানি দেখতে হবে। বিজ্ঞানী কুলম্ব দুটি বিন্দু চার্জের মাঝে কতখানি বল কাজ করে সেটা বের করেছিলেন। এ রকম একটা বলের সূত্র আমরা এর মাঝে একটা দেখে ফেলেছি সেটা হচ্ছে নিউটনের মহাকর্ষ বলের সূত্র। সেটি ছিল এ রকম:",
    "[চিত্র ১০.০৯: দুটি চার্জ $q_1$ এবং $q_2$ এর ভেতর বল $F$, আকর্ষণ এবং বিকর্ষণ দুই-ই হতে পারে।]",
    "$$F = G\\frac{m_1m_2}{r^2}$$",
