    "$$k = 9 \\times 10^9 \\text{Nm}^2/\\text{C}^2$$",
    "কুলম্ব হচ্ছে চার্জের একক, আমরা পরের অধ্যায়েই দেখব চার্জের প্রবাহ হচ্ছে বৈদ্যুতিক প্রবাহ বা কারেন্ট এবং কারেন্টের একক হচ্ছে অ্যাম্পিয়ার। এক সেকেন্ডব্যাপী এক অ্যাম্পিয়ার কারেন্ট প্রবাহিত করা হলে প্রবাহিত চার্জের পরিমাণ হচ্ছে এক কুলম্ব (C)।",
    "তবে কুলম্ব বোঝার সবচেয়ে খাঁটি পদ্ধতি হচ্ছে ইলেকট্রন বা প্রোটনের চার্জের পরিমাণটি বোঝা। তার পরিমাণ",
