    "তুমি যেটা স্পর্শ করছ তার পটেনশিয়াল পজিটিভ বা নেগেটিভ দুটোই হতে পারে। এক জায়গায় তোমার শরীর থেকে চার্জ (ইলেকট্রন) যাবে অন্য ক্ষেত্রে তোমার শরীরে চার্জ আসবে, দুটোই বিদ্যুৎ প্রবাহ—শুধু দিকটা ভিন্ন।",
