    "আমরা আগের অধ্যায়ে দেখেছি যে যদি দুটো ভিন্ন বস্তুর পটেনশিয়াল বা বিভবের মাঝে পার্থক্য থাকে তাহলে যেটার বেশি বিভব সেখান থেকে যেটার বিভব কম সেখানে চার্জ বা আধান প্রবাহিত হয়। যতক্ষণ পর্যন্ত বিভব দুটো সমান না হচ্ছে চার্জের প্রবাহ হতেই থাকে। চার্জের এই প্রবাহ হচ্ছে তড়িৎ বা বিদ্যুতের প্রবাহ, আমরা যেটাকে সাধারণভাবে ‘ইলেকট্রিসিটি’ বলি, যেটা দিয়ে লাইট জ্বলে, ফ্যান ঘোরে, মোবাইল টেলিফোন চার্জ দেওয়া হয়।",
    "চিত্র ১১.০১ : চার্জ সংযুক্ত গোলক থেকে চার্জহীন গোলককে বিদ্যুৎ প্রবাহ।",
    "১১.১.১ তড়িৎ চালক শক্তি এবং বিভব পার্থক্য",
    "একটা বিষয় নিশ্চয়ই বুঝতে পারছ, পটেনশিয়াল বা বিভব এর পার্থক্য থাকলেই শুধু বিদ্যুৎপ্রবাহ হয়, তাই আমরা যদি বিদ্যুৎপ্রবাহ অবিচ্ছিন্ন রাখতে চাই, তাহলে বিভবের পার্থক্যটাও বজায় রাখতে হবে, সেটাকে কমে সমান হয়ে যেতে দেওয়া যাবে না। যদি দুটো ধাতব গোলকের একটির মাঝে ধনাত্মক চার্জ দিয়ে সেখানে একটি বিভব তৈরি করে চার্জবিহীন অন্য গোলকটির সাথে একটি তার দিয়ে জুড়ে দিই (চিত্র ১১.০১), তাহলে বিদ্যুতের প্রবাহ শুরু হবার সাথে সাথে পটেনশিয়াল বা বিভব এর পার্থক্য কমতে থাকবে এবং মুহূর্তের মাঝে দুটি বিপরীত বিভব সমান হয়ে যাবে। একটি সমান্তরাল-পাত ধারক বা ক্যাপাসিটরের দুটো সমান্তরাল ধাতব পাতের উপর আধান বা চার্জ জমা রেখে বিভবের পার্থক্য তৈরি করা সম্ভব। ধারকের সেই দুটো পাত একটা তার দিয়ে জুড়ে দিলেও মুহূর্তের মাঝে পুরো চার্জ প্রবাহিত হয়ে তাদের বিভব সমান হয়ে যাবে। কাজেই বুঝতেই পারছ আমরা যদি ব্যবহার করার মতো সার্বক্ষণিক বিদ্যুৎ চাই তাহলে অন্য কোনো পদ্ধতি দরকার যেটা এমন একটা পটেনশিয়াল বা বিভব পার্থক্য তৈরি করে দেবে যেন চার্জ প্রবাহিত হলেও তার পার্থক্য কমে না যায়।",
    "২৯৩"
