    "আমরা আগেই বলেছি বিভবের মানটি গুরুত্বপূর্ণ নয়, তার পার্থক্যটুকু গুরুত্বপূর্ণ। তাই দেখবে অনেক সময় একটা ব্যাটারির এক মাথার পটেনশিয়ালের মান ভিন্ন করে ফেলা সম্ভব, কিন্তু পার্থক্যটা সব সময়ই সমান থাকবে।",
