    "ধারক বা Capacitor-কে কি ব্যাটারি হিসেবে ব্যবহার সম্ভব?",
    "১১.১.২ পরিবাহী, অপরিবাহী এবং অর্ধপরিবাহী পদার্থ",
    "পরিবাহী পদার্থ: আমরা যদি পদার্থের গঠনটা ভালো করে বুঝে থাকি, তাহলে একটা বিষয় খুব ভালো করে জেনেছি। কঠিন পদার্থে তার অণু-পরমাণু শক্ত করে নিজের জায়গায় বসে থাকে। তাপমাত্রা বাড়লে তারা নিজের জায়গায় কাঁপাকাঁপি করতে পারে কিন্তু সেখান থেকে সরে অন্য জায়গায় চলে যায় না। তোমাদের রসায়ন বইয়ে তোমরা যখন ধাতব বন্ধন পড়েছ সেখানে দেখেছ, ধাতব পরমাণুর কিছু ইলেকট্রন প্রায় মুক্ত অবস্থায় থাকে এবং সেগুলো এক জায়গা থেকে অন্য জায়গায় যেতে পারে। সেজন্য আমরা সেগুলোকে বলি পরিবাহী পদার্থ। সোনা, রুপা, তামা, অ্যালুমিনিয়াম এগুলো সুপারিবাহী।",
