    "এবারে আমরা সত্যিকারের বর্তনী বা সার্কিটে সত্যিকারের বিদ্যুৎপ্রবাহ নিয়ে আলোচনা করব। আমরা অনেকবার বলেছি যে দুটি বিন্দুতে যদি পটেনশিয়াল বা বিভব পার্থক্য থাকে এবং আমরা যদি একটি পরিবাহী তার দিয়ে সেই দুটি বিন্দুকে জুড়ে দিই, তাহলে বিন্দু দুটির ভেতরে বিদ্যুৎ প্রবাহ হবে, কিন্তু কতটুকু বিদ্যুৎপ্রবাহ হবে সেটি নিয়ে এখনো কিছু বলা হয়নি। শুধু তা-ই নয়, একটা সোনার পরিবাহী তার দিয়ে জুড়ে দিলে যেটুকু বিদ্যুৎ প্রবাহিত হবে একটা লোহার তার জুড়ে দিলেও কি সমান পরিমাণ বিদ্যুৎ প্রবাহিত হবে?",
    "১১.২.১ ও'মের সূত্র (Ohm's Law)",
    "পটেনশিয়াল বা বিভব পার্থক্য এবং তড়িৎপ্রবাহের মাঝে সম্পর্ক দেখার জন্য আমরা একটা পরীক্ষণ করতে পারি। বিভব মাপার জন্য যে যন্ত্রটি ব্যবহার করা হয় তার নাম ভোল্টমিটার, বিদ্যুৎপ্রবাহ বা কারেন্ট মাপার জন্য যে যন্ত্র ব্যবহার করা হয় সেটার নাম অ্যামিটার। (আসলে একই যন্ত্রের সুইচ ঘুরিয়ে এটাকে কখনো ভোল্টমিটার বা কখনো অ্যামিটার হিসেবে ব্যবহার করা যায়) আমরা কয়েকটা ব্যাটারি নিতে পারি, একটা ব্যাটারির জন্য তড়িৎ চালক শক্তি 1.5 V হলে দুটি ব্যাটারির তড়িৎ চালক শক্তি 2 × 1.5 =",
    "চিত্র ১১.০৪: রেজিস্ট্যান্সের কারণে বিভব পার্থক্যের সাপেক্ষে বিদ্যুৎপ্রবাহ।",
