  "312": [
    "চল বিদ্যুৎ ৩০৭",
    "একটা নির্দিষ্ট পদার্থের জন্য $\\rho$ হচ্ছে আপেক্ষিক রোধ এবং তাই এর একক হচ্ছে $\\Omega\\text{ m}$।",
    "কোনো পদার্থ কতটুকু বিদ্যুৎ পরিবাহী সেটা বোঝানোর জন্য পরিবাহিতা বলে একটা রাশি $\\sigma$ তৈরি করা হয়েছে, যে পদার্থ যত বেশি বিদ্যুৎ পরিবাহী তার পরিবাহিতা তত বেশি, যেটা আপেক্ষিক রোধ $\\rho$ (টেবিল ১১.০১) এর ঠিক বিপরীত।",
    "$$\\sigma = \\frac{1}{\\rho}$$",
    "পরিবাহিতা $\\sigma$ এর একক হচ্ছে $(\\Omega\\text{ m})^{-1}$",
    "এখানে একটা বিষয় মনে রাখতে হবে কোনো পদার্থের রোধ হচ্ছে ইলেকট্রন প্রবাহের বাধা, অণু-পরমাণুগুলো যত বেশি কাঁপাকাঁপি করে একটা ইলেকট্রন তাদের ভেতর দিয়ে যেতে তত বেশি বাধাগ্রস্ত হয়, কিংবা তার রোধ তত বেশি। তাপমাত্রা বাড়িয়ে দিলে যেহেতু অণু-পরমাণুগুলো বেশি কাঁপাকাঁপি করে, তাই সব সময়ই তাপমাত্রা বাড়ালে পরিবাহী পদার্থের আপেক্ষিক রোধ বেড়ে যায়। সেজন্য যখন কোনো পদার্থের রোধ বা আপেক্ষিক রোধ প্রকাশ করতে হয় তখন তার জন্য তাপমাত্রাটা নির্দিষ্ট করে বলে দিতে হয়।",
    "স্থির মানের রোধ: বিভিন্ন বর্তনী বা সার্কিটে ব্যবহার করার জন্য নির্দিষ্ট মানের রোধ বা রেজিস্টর ব্যবহার করা হয়। এগুলো নানা আকারের এবং নানা ধরনের হতে পারে। ল্যাবরেটরিতে ব্যবহার করার জন্য যে রোধ ব্যবহার করা হয় সাধারণত তার উপরে বিভিন্ন রঙের ব্যান্ডর মাধ্যমে তার মান প্রকাশ করা হয়। একটি রোধের মান ছাড়াও সেটি কত বৈদ্যুতিক ক্ষমতা সহ্য করতে পারবে সেটিও নির্দিষ্ট করে দেওয়া থাকে।",
    "টেবিল ১১.০১: পদার্থের আপেক্ষিক রোধ",
    "| পদার্থ | আপেক্ষিক রোধ ($\\Omega\\text{ m}$) |",
    "| :--- | :--- |",
    "| রূপা | $1.59 \\times 10^{-8}$ |",
    "| তামা | $1.68 \\times 10^{-8}$ |",
    "| সোনা | $2.44 \\times 10^{-8}$ |",
    "| গ্রাফাইট | $2.50 \\times 10^{-6}$ |",
    "| হীরা | $1.00 \\times 10^{12}$ |",
    "| বাতাস | $1.30 \\times 10^{16}$ |",
    "(a) (b)",
    "চিত্র ১১.০৬: (a) স্থির এবং (b) পরিবর্তী রোধ"
  ],
  "313": [
    "৩০৮ পদার্থবিজ্ঞান",
    "পরিবর্তী রোধ: মাঝে মাঝেই কোনো বৈদ্যুতিক বর্তনীতে একটি রোধের প্রয়োজন হয়, যেটির মান প্রয়োজনমতো পরিবর্তন করা যেতে পারে। যে ধরনের রোধের মান একটি নির্দিষ্ট সীমার ভেতরে পরিবর্তন করা যায় সেটিকে পরিবর্তী রোধ বা রিওস্টেট বলে। স্থির রোধের দুটি প্রান্ত থাকে, পরিবর্তী রোধে দুই প্রান্ত ছাড়াও মাঝখানে আরেকটি প্রান্ত থাকে, যেখানে পরিবর্তন করা রোধের মানটুকু পাওয়া যায়। ১১.০৬ চিত্রে স্থির এবং পরিবর্তী রোধের ছবি দেখানো হয়েছে।",
    "উদাহরণ",
    "প্রশ্ন: রুপা, তামা, টাংস্টেন ও নাইক্রোম তারের আপেক্ষিক রোধ $\\rho$ যথাক্রমে $1.6 \\times 10^{-8} \\ \\Omega \\text{m}$, $1.7 \\times 10^{-8} \\ \\Omega \\text{m}$, $5.5 \\times 10^{-8} \\ \\Omega \\text{m}$ ও $100 \\times 10^{-8} \\ \\Omega \\text{m}$ এসব পদার্থের $1 \\text{ m}^2$ প্রস্থচ্ছেদ ক্ষেত্রফল বিশিষ্ট তার ব্যবহার করে $1 \\ \\Omega$ রোধ তৈরি করো।",
    "উত্তর: আমরা জানি, রোধ",
    "$R = \\frac{\\rho L}{A}$",
    "যেখানে $L$ দৈর্ঘ্য এবং $A$ প্রস্থচ্ছেদ।",
    "এখানে $A = 1 \\text{ m}^2$",
    "$L = \\frac{RA}{\\rho} = \\frac{1 \\times 1 \\ \\Omega \\text{m}^2}{\\rho} = \\frac{1 \\ \\Omega \\text{m}^2}{\\rho}$",
    "রূপার জন্য:",
    "$L = \\frac{1 \\text{m}}{1.6 \\times 10^{-8}} = 6.25 \\times 10^7 \\text{ m}$",
    "তামার জন্য:",
    "$L = \\frac{1 \\text{m}}{1.7 \\times 10^{-8}} = 5.9 \\times 10^7 \\text{ m}$",
    "টাংস্টেনের জন্য:",
    "$L = \\frac{1 \\text{m}}{5.5 \\times 10^{-8}} = 1.8 \\times 10^7 \\text{ m}$",
    "নাইক্রোমের জন্য:",
    "$L = \\frac{1 \\text{m}}{100 \\times 10^{-8}} = 10^6 \\text{ m}$",
    "দেখতেই পাচ্ছ $1 \\ \\Omega$ রোধ তৈরি করার জন্য অনেক দীর্ঘ (প্রায় লক্ষ কিলোমিটার) পদার্থ নিতে হয়। বাস্তবে কখনোই $A = 1 \\text{ m}^2$ হয় না দৈনন্দিন ব্যবহারের জন্য অনেক সরু তার ব্যবহার করা হয়। যদি $0.1 \\text{ mm}$ ব্যাসার্ধের প্রস্থচ্ছেদ নির্দিষ্ট করে দিই তাহলে $1 \\ \\Omega$ রোধ তৈরি করতে কত দীর্ঘ তারের প্রয়োজন?",
    "২০২৭"
  ],
