    "আমরা সবাই আমাদের জীবনে কখনো না কখনো চুম্বকের আকর্ষণ এবং বিকর্ষণ দেখে চমৎকৃত হয়েছি। আপাতদৃষ্টিতে চুম্বকত্ব এবং বিদ্যুৎপ্রবাহকে পুরোপুরি ভিন্ন দুটি বিষয় বলে মনে হলেও এই দুটোই যে একই শক্তির ভিন্ন রূপ সেটি এই অধ্যায়ে আলোচনা করা হবে। আমরা দেখব বিদ্যুতের প্রবাহ হলে যেরকম চৌম্বক ক্ষেত্র তৈরি হতে পারে ঠিক সেরকম চৌম্বক ক্ষেত্রকে পরিবর্তন করে বিদ্যুৎ প্রবাহ করা যেতে পারে।",
