    "একটা তার যদি সোজা থাকে এবং তার ভেতর দিয়ে বিদ্যুৎপ্রবাহ হলে চৌম্বক বলরেখা কেমন হয় সেটা ১২.০৩ চিত্রে দেখানো হয়েছিল। যদি তারটা সোজা না হয়ে বৃত্তাকার হয় তাহলে চৌম্বক বলরেখা কেমন হবে? ১২.০৫ চিত্রে সেটা দেখানো হয়েছে। বুঝতেই পারছ বিদ্যুৎপ্রবাহ যত বেশি হবে, চৌম্বক ক্ষেত্রটি তত শক্তিশালী হবে।",
    "একটা তারের ভেতর দিয়ে কতখানি বিদ্যুৎ প্রবাহিত করা যায় তার একটা সীমা আছে, তারটা I²R হিসেবে গরম হয়ে যায় তা ছাড়াও সবচেয়ে বেশি কতখানি বিদ্যুৎ প্রবাহ দেওয়া সম্ভব সেটা বিদ্যুতের উৎসের ওপর নির্ভর করে। তাই যদি শক্তিশালী চৌম্বক ক্ষেত্র তৈরি করতে হয় তাহলে একটা মাত্র বৃত্তাকার লুপ-এর ওপর নির্ভর না করে অপরিবাহী আস্তরণ দিয়ে ঢাকা তার দিয়ে অনেকবার প্যাঁচিয়ে।",
