    "বিদ্যুতের চৌম্বক ক্রিয়া ৩৩৭",
    "তড়িৎচুম্বকটিকে যদি তার কেন্দ্র বরাবর একটা অক্ষে ঘুরতে দেওয়া হয় তাহলে এটি পরের চিত্রের মতো অবস্থানে যাওয়ার চেষ্টা করবে।",
    "চিত্র ১২.১০: বৈদ্যুতিক মোটর একটি তড়িৎচুম্বকের ভেতর দিয়ে এমনভাবে পরিবর্তী বিদ্যুৎ প্রবাহ করানো হয়, যেন সব সময়েই এটি ঘুরতে থাকে।",
    "যদি কোনো বিশেষ অবস্থা তৈরি করে পরের অবস্থানে যাওয়ার সাথে সাথে তড়িৎচুম্বকটির বিদ্যুৎপ্রবাহের দিক পরিবর্তন করে দেওয়া যায়, তাহলে সেখানে পৌঁছানোর সাথে সাথে কয়েল দিয়ে তৈরি দণ্ড চুম্বকটির উত্তর মেরু দক্ষিণ মেরুতে আর দক্ষিণ মেরু উত্তর মেরুতে পাল্টে যাবে, তাই বিকর্ষণের কারণে আবার সেটি সরে যাবার চেষ্টা করবে অর্থাৎ এটি একটি ঘূর্ণন তৈরিকারী টর্ক বা ভ্রামক অনুভব করবে। এটি চেষ্টা করবে পরের স্থায়ী অবস্থানে পৌঁছাতে কিন্তু সেখানে পৌঁছানোর সাথে সাথে আবার এটার বিদ্যুতের দিক পরিবর্তন করে দিলে এটি সেখানে থেমে যাবে না, আবার ঘুরতে শুরু করবে। তাই যখনই এটা একটা সাম্যাবস্থানে পৌঁছাবে তখনই যদি এটাতে এমনভাবে বিদ্যুৎ প্রবাহ করানো হয় যেন বিকর্ষণের কারণে এটি একটি ঘূর্ণন সৃষ্টিকারী টর্ক বা ভ্রামক অনুভব করে তাহলে এটি ঘুরতেই থাকবে।",
    "বিদ্যুতের দিক পরিবর্তন করার জন্য কমিউটেটর নামে একটি উপকরণের মাধ্যমে খানিকটা যান্ত্রিক কৌশল ব্যবহার করতে হয়। মূল কয়েল যে অক্ষে ঘুরতে থাকে সেই ঘূর্ণায়মান অক্ষটির দুই পাশে তড়িৎ চুম্বকের দুটি তার এমনভাবে বসানো হয় যেন সেটি কমিউটেটরে মূল বিদ্যুৎপ্রবাহের টার্মিনালকে স্পর্শ করে থাকে। যখনই স্পর্শ করে তখনই এমনভাবে বিদ্যুৎ প্রবাহিত করবে যেন সব সময় সেটি তড়িৎচুম্বকটিকে বিকর্ষণ করে সরিয়ে দেওয়ার চেষ্টা করে। মাঝামাঝি সময়ে যখন",
    "চিত্র ১২.১১: একটি বৈদ্যুতিক মোটর।",
    "ফর্মা-৪৩, পদার্থবিজ্ঞান, ৯ম-১০ম শ্রেণি"
