    "৩৪০ পদার্থবিজ্ঞান",
    "১২.৩.২ ট্রান্সফর্মার (Transformer)",
    "চৌম্বক ক্ষেত্রের পরিবর্তন হলে বিদ্যুৎ তৈরি হয়– এই নীতি ব্যবহার করে ট্রান্সফর্মার তৈরি করা হয়। ট্রান্সফর্মার কীভাবে কাজ করে বোঝার জন্য ১২.১৩ চিত্রে একটা আয়তাকার লোহার মজ্জা বা কোর দেখানো হয়েছে। এই কোরের দুই পাশে পরিবাহী তার প্যাঁচানো হয়েছে– অবশ্যই এই পরিবাহী তারের ওপর অপরিবাহী আস্তরণ রয়েছে, যেন এটা ধাতব কোনো কিছুকে স্পর্শ করলেও 'শর্ট সার্কিট' না হয়। চিত্রে দেখানো হয়েছে কোরের বাম পাশে একটা এসি ভোল্টেজের উৎস লাগানো হয়েছে। তারটি যেহেতু লোহার কোরকে ঘিরে লাগানো হয়েছে তাই যখন বিদ্যুৎ প্রবাহিত হবে, তখন লোহার ভেতরে চৌম্বকত্ব তৈরি হবে এবং সেই চৌম্বক বলরেখা আয়তাকার লোহার ভেতর দিয়ে যাবে।",
    "আমরা যেহেতু এসি ভোল্টেজের উৎস লাগিয়েছি তাই লোহার কোরে চৌম্বকত্ব বাড়বে-কমবে এবং দিক পরিবর্তন করবে, অর্থাৎ ক্রমাগত চৌম্বক ক্ষেত্রের পরিবর্তন হবে। লোহার কোরের অন্য পাশেও তার প্যাঁচানো আছে (অবশ্যই অপরিবাহী আবরণে ঢাকা) সেই কয়েলের মাঝে লোহার কোরের ভেতর দিয়ে চৌম্বক ক্ষেত্রটির ক্রমাগত পরিবর্তন হতে থাকবে এবং এই পরিবর্তন ডান পাশের কয়েলে একটা তড়িৎচালক শক্তি বা EMF তৈরি করবে– একটা ভোল্টমিটারে আমরা সেটা ইচ্ছে করলে পরিমাপ করতে পারব। এই পদ্ধতিতে সরাসরি বৈদ্যুতিক সংযোগ ছাড়াই একটি কয়েল থেকে অন্য কয়েলে বিদ্যুৎ পাঠানো যায়। যে যন্ত্রের মাধ্যমে এই কাজ করা হয় তাকে ট্রান্সফর্মার বলে।",
    "এই ট্রান্সফর্মার দিয়ে আমরা অত্যন্ত চমকপ্রদ কিছু বিষয় করতে পারি। দুই পাশে কয়েলের প্যাঁচসংখ্যা যদি সমান হয়, তাহলে বাম দিকে আমরা যে এসি ভোল্টেজ প্রয়োগ করব ডান দিকে ঠিক সেই এসি ভোল্টেজ ফেরত পাব। ডান দিকে প্যাঁচের সংখ্যা যদি দশ গুণ বেশি হয় তাহলে ভোল্টেজ দশ গুণ বেশি হবে। প্যাঁচের সংখ্যা যদি দশ গুণ কম হয় তাহলে ভোল্টেজ দশ গুণ কম হবে। বাম দিকের কয়েল যেখানে এসি ভোল্টেজ প্রয়োগ করা হয়, তার নাম প্রাইমারি কয়েল বা মুখ্য কুণ্ডলী এবং ডান দিকে যেখানে ভোল্টেজ আবিষ্ট হয় তার নাম সেকেন্ডারি কয়েল বা গৌণ কুণ্ডলী।",
    "তোমরা হয়তো মনে করতে পারো যদি সত্যি এটা ঘটানো সম্ভব হয় তাহলে আমরা প্রাইমারিতে অল্পসংখ্যক প্যাঁচ দিয়ে অল্প ভোল্টেজ প্রয়োগ করে, সেকেন্ডারি কয়েলে অনেক বেশি প্যাঁচ দিয়ে বিশাল একটা ভোল্টেজ বের করে অফুরন্ত বৈদ্যুতিক শক্তির ব্যবস্থা করে ফেলি না কেন? এখানে একটি বিষয় মনে রাখতে হবে প্রতি সেকেন্ডে কতটুকু বৈদ্যুতিক শক্তি প্রয়োগ করা হচ্ছে, সেটা পরিমাপ করা হয় VI (ভোল্টেজ x কারেন্ট) দিয়ে, একটা ট্রান্সফর্মারে প্রাইমারিতে যে পরিমাণ VI",
    "চিত্র ১২.১৩: ট্রান্সর্মারের প্রাইমারি কয়েলে এসি বিভব পার্থক্য প্রয়োগ করা হলে সেকেন্ডারি কয়েলে সেটি বিভব পার্থক্য তৈরি করে।"
