    "MATERIAL",
    "চিত্র ১৩.০২: তেজস্ক্রিয় পদার্থ ঝুঁকিপূর্ণ বলে এগুলোকে খুব সতর্কতার সাথে ব্যবহার করতে হয়। তেজস্ক্রিয়তার সতর্কতামূলক চিহ্ন।",
